/* Trims off trailing zeros from a string representing a double. */
int trimDoubleString(char *buf, size_t len) {
    utilHub.fp_len = (int)len;
    utilHub.fp_err = 0;

    if (strchr(buf,'.') != NULL) {
        char *p = buf+len-1;
        while(*p == '0') {
            p--;
            len--;
        }
        if (*p == '.') len--;
    }
    buf[len] = '\0';
    return len;
}

